import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易口訣義 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易口訣義 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"classics/koujueyi/048.md","filePath":"classics/koujueyi/048.md"}'),r={name:"classics/koujueyi/048.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>彖曰：柔以時升，巽而順，剛中而應，是以大亨。「用見大人勿恤」，有慶也。「南征吉」，志行也。</p><p>象曰：地中生木，「升」，君子以順德，積小以成高大。</p><p>初六：允升，大吉。</p><p>象曰：「允升大吉」，上合志也。</p><p>九二：孚乃利用礿，無咎。</p><p>象曰：九二之「孚」，有喜也。</p><p>九三，升虛邑。</p><p>象曰：「升虛邑」，無所疑也。</p><p>六四：王用亨於岐山，吉，無咎。</p><p>象曰：「王用亨於岐山」，順事也。</p><p>六五：貞吉，升階。</p><p>象曰：「貞吉升階」，大得志也。</p><p>上六：冥升，利於不息之貞。</p><p>象曰：「冥升」在上，消不富也。</p><p>解讀</p><p>「升元亨」者，升者漸進之名，登升之義，計必大通，故曰「元亨」。褚氏雲：「猶人日思善道，進而不已，其德日新，故能亨也。」「用見大人，勿恤」者，剛不居中，無以統御於下，故須用見德大之人，然後無復憂恤也。「南征吉」者，南是陽明之方，當升之時，若往陰方，即彌加闇昧。既見德大之人，復宜適陽明之方，即升進之道通矣。二方以喻人之明昧也。象曰「地中生木，升」者，升是漸漸登升道長之義，亦猶地中生木，從下升高，自微至著也。「君子以順德，積小以成高大」者，孔義雲：「君子象之，所以順行其德，積其小善，以成高大。」又何妥雲：「君子謹習為先，修習道德，積其微小，以至高大。」案：此之義，「順」字恐當為「慎」也。</p><p>「初六允升，大吉」者，允，當也；二三皆有應於上，故升之不疑。唯初六上無其應，體又柔劣，不能自進，當九二、九三升進之時，與之俱行，上合志，必大得矣，故曰「允升，大吉」，亦猶九二、九三「許允」，即獲吉也。</p><p>九二「孚乃利用礿，無咎」者，九二與五為應，九二前進，五必信任，故曰「有孚」也。二體剛中，誠乎信實，進不求寵，志弘大業，直是享薦神明，但可儉約薄省而己，亦得喜慶臻至，更有何咎？故「利用礿，無咎」，蓋為上應於君矣。</p><p>「九三升虛邑」者，以剛得位，己以進前，上體應柔，不拒於己，若升其虛邑，無所疑滯，故小象雲「無所疑」也。</p><p>六四「王用亨於岐山，吉，無咎」者，體柔居四，下體三爻皆悉上升，處升之際，可納而不可拒，其猶太王避狄之難，居岐山之會，故曰「王用亨於岐山」也。若能因物而成，順事之情，納而不拒，所以得「吉」而「無咎」，故曰「吉，無咎」也。</p><p>六五「貞吉，升階」者，以柔居尊，不自專制，委任九二，任用得人，故得保其升階而踐貴位也。</p><p>「上六冥升，利於不息之貞」者，冥猶瞑也。既處升極而更升進，即是瞑暗不得明瞭，而猶求升，故曰「冥升」。若冥然求升，欲為物之主者，即喪亡交至，如克己修身而不暫息，施於正即利莫大焉，故曰「利於不息之貞」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
